5: 
6: class NewsListPage extends StatefulWidget {
7:   const NewsListPage({super.key});
8: 
9:   @override
10:   State<NewsListPage> createState() => _NewsListPageState();
11: }
12: 
13: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   late Future<List<NewsModel>> _cachedNewsListFuture;
17: 
18:   List<NewsModel>? _news;
19: 
20:   late final AnimationController _scaleController;
21:   late final Animation<double> _scaleAnimation;
22: 
23:   @override
24:   void initState() {
25:     super.initState();
26:     _initAnimation();
27:     _initData();
28:   }
29: 
30:   @override
31:   void dispose() {
32:     _scaleController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _scaleController = AnimationController(
38:       vsync: this,
39:       duration: Duration(milliseconds: 200),
40:     );
41:     _scaleAnimation = _tween.animate(_scaleController);
42:   }
43: 
44:   void _initData() {
45:     final NewsRepository newsRepository = context.read<NewsRepository>();
46: 
47:     // cache-then-network: мгновенно отдаём кэш ленты, сеть запрашиваем параллельно
48:     _cachedNewsListFuture = newsRepository.loadNewsFeed(NewsFeedFilter.all);
49: 
50:     _refreshFromNetwork(newsRepository);
51:   }
52: 
53:   void _refreshFromNetwork(NewsRepository newsRepository) {
54:     newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then(
55:       (List<NewsModel> fresh) {
56:         if (!mounted) return;
57: 
58:         setState(() {
59:           _news = fresh;
60:           _scaleController.forward(from: 0); // запускаем анимацию
61:         });
62:       },
63:       onError: (Object _) {
64:         // сеть недоступна — остаёмся на кэше ленты
65:       },
66:     );
67:   }
68: 
69:   @override
70:   Widget build(BuildContext context) {
71:     return Scaffold(
72:       appBar: AppBar(title: Text(context.loc.news)),
73:       body: FutureBuilder<List<NewsModel>>(
74:         future: _cachedNewsListFuture,
75:         builder: (BuildContext context, AsyncSnapshot<List<NewsModel>> snapshot) {
76:           final List<NewsModel>? data = _news ?? snapshot.data;
77:           if (data == null || data.isEmpty) return const SizedBox.shrink();
78: 
79:           return ScaleTransition(
80:             scale: _scaleAnimation,
81:             child: ListView.builder(
82:               itemCount: data.length,
83:               itemBuilder: (BuildContext context, int index) {
84:                 final NewsModel news = data[index];
85: 
86:                 return Padding(
87:                   key: ValueKey(news.link),
88:                   padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
89:                   child: NewsCard(model: news),
90:                 );
91:               },
92:               padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
93:             ),
94:           );
95:         },
96:       ),
97:     );
98:   }
99: }
